		@Parameter(name = "X-Model", description = "단말 모델명", example = "SM-G998N", required = true, in = ParameterIn.HEADER),
		@Parameter(name = "X-OS-Version", description = "Android OS 버전", example = "14", required = true, in = ParameterIn.HEADER),
		@Parameter(name = "X-App-Version", description = "앱 버전", example = "02.00.01", required = true, in = ParameterIn.HEADER)
	})
	@RequestBody(
		description = "가입자 초기 정보 확인 요청",
		required = true,
		content = @Content(mediaType = "application/json",
		schema = @Schema(type = "object"),
		examples = @ExampleObject(value = "{\"ctn\":\"01012345678\",\"fcmToken\":\"fcm_token_value\"}"))
	)
	@NoAuth
	@RequestMapping(value = "/init", method = RequestMethod.POST)
	public String init(@RequestJson(requiredValues = {"ctn", "fcmToken"}) ParamMap param,
					   @RequestHeader(value = "X-Manufacturer", required = true) String manufacturer,
					   @RequestHeader(value = "X-Model", required = true) String deviceModel,
					   @RequestHeader(value = "X-OS-Version", required = true) String osVersion,
					   @RequestHeader(value = "X-App-Version", required = true) String appVersion,
					   HttpServletRequest request, Model model) throws LogicException {
		LogInfo logInfo = setDeviceLog(param, "S01");
		try {
			model.addAllAttributes(service.initClient(param, request));
			logInfo.setRESULT_CODE("000");
		} catch (LogicException le) {
			logInfo.setRESULT_CODE(le.getCode());
			throw new LogicException(le.getMessage(), le.getCode());
		} finally {
			lgLogger.info(logInfo.toString());
		}
		return JSON_VIEW;
	}

	/**
	 * 신규 API - 동기화(임시)
	 * GET /client/sync
	 * 인증: 인터셉터에서 처리 (Authorization: Bearer {ACCESS_TOKEN})
	 * 요청 파라미터: 없음
