	 */
	@Operation(summary = "동기화 (신규)", description = "신규 API 규격 - 클라이언트 동기화 데이터를 조회합니다")
	@Parameters({
		@Parameter(name = "X-Manufacturer", description = "단말 제조사", example = "samsung", required = true, in = ParameterIn.HEADER),
		@Parameter(name = "X-Model", description = "단말 모델명", example = "SM-G998N", required = true, in = ParameterIn.HEADER),
		@Parameter(name = "X-OS-Version", description = "Android OS 버전", example = "14", required = true, in = ParameterIn.HEADER),
		@Parameter(name = "X-App-Version", description = "앱 버전", example = "02.00.01", required = true, in = ParameterIn.HEADER),
		@Parameter(name = "Authorization", description = "인증 토큰", example = "Bearer {ACCESS_TOKEN}", required = true, in = ParameterIn.HEADER)
	})
