	private LogInfo setDeviceLog(ParamMap param, String serviceClass) {
		String clientName = "";
		if (!CommonUtil.isNull(param.getSessionAttribute("clientName"))) {
			clientName = CommonUtil.nvl((String)param.getSessionAttribute("clientName"));
		}
		LogInfo logInfo = new LogInfo("SVC"
				, param.getRequest().getRemoteAddr()
				, CommonUtil.nvl((String)param.getSessionAttribute("deviceInfo"))
				, CommonUtil.nvl((String)param.getSessionAttribute("osInfo"))
				, CommonUtil.nvl((String)param.getSessionAttribute("networkInfo"))
				, ""
				, CommonUtil.nvl((String)param.getSessionAttribute("deviceModel"))
				, "1"
				, ""																	// MEMBER_ID
				, serviceClass
				, ""
				, ""
				, ""
				, CommonUtil.nvl((String)param.getSessionAttribute("exceptionPolicy"))
				, clientName);
		if (!CommonUtil.isNull(param.getSessionAttribute("memberSeq"))) {
			logInfo.setMEMBER_ID(CommonUtil.memberIdFormat(param.getSessionLong("memberSeq")));
		}
		if (!CommonUtil.isNull(param.getSessionAttribute("clientSeq"))) {
			logInfo.setCLIENT_ID(CommonUtil.clientIdFormat(param.getSessionLong("clientSeq")));
		}
		return logInfo;
	}
