@ResponseStatus(HttpStatus.OK)
@ResponseBody
@ExceptionHandler(Exception.class)
public ModelAndView exceptionHandler(HttpServletRequest request, HttpServletResponse response, Exception ex) {
	logger.debug("start URI : " + request.getRequestURI());

	String code;
	String message;

	switch (ex) {
		case MissingRequestHeaderException mrhEx -> {
			code = Constants.MISSING_REQUIRED_VALUE_CODE;
			message = Constants.MISSING_REQUIRED_VALUE_MSG + ": " + mrhEx.getHeaderName();
		}
		case LogicException le -> {
			code = le.getCode();
			message = le.getMessage();
		}
		case RuntimeLogicException rle -> {
			code = rle.getCode();
			message = rle.getMessage();
		}
		case MyBatisSystemException mbEx -> {
			if (mbEx.getMessage() != null
					&& mbEx.getMessage().contains("TooManyResultsException")) {
				code = Constants.TOO_MANY_RESULTS_CODE;
				message = Constants.TOO_MANY_RESULTS_MSG;
			} else {
				code = Constants.DB_CONNECTION_FAIL_CODE;
				message = Constants.DB_CONNECTION_FAIL_MSG;
			}
		}
		default -> {
			code = Constants.UNKNOWN_ERR_CODE;
			message = Constants.UNKNOWN_ERR_MSG;
			logger.error("Unhandled exception [{}]: {}", ex.getClass().getSimpleName(), ex.getMessage(), ex);
		}
	}

	if (!(ex instanceof MyBatisSystemException) && !Constants.UNKNOWN_ERR_CODE.equals(code)) {
		logger.error("Handled exception [{}] code={}, message={}", ex.getClass().getSimpleName(), code, message);
	}

	return buildErrorResponse(code, message);

