	public ResultMap makeExcel(ParamMap param) throws Exception {
        ResultMap result = new ResultMap();
        String searchType = param.getString("searchType");
        String searchValue = param.getString("searchValue");
        if ("CTN".equals(searchType)) {
            if (searchValue != null && !searchValue.equals("")) {
                param.put("searchValue", hashUtil.hmacSha256(searchValue));
            }
        } else {
            param.put("searchValue", URLDecoder.decode(searchValue, "UTF-8"));
        }

        System.out.println("excelReason : " + param.getString("excelReason"));

        Thread excelMakerThread = new Thread(new HistoryService.ExcelMaker(param));
        excelMakerThread.start();

        return result;
    }
	
	class ExcelMaker implements Runnable {
        ParamMap param = new ParamMap();

        public ExcelMaker(ParamMap param) {
            this.param = param;
        }

        private void generateExcelFile(ResultMap result) {
            InputStream in = null;
            try {
                XLSTransformer transformer = new XLSTransformer();

                in = s3FileService.downloadStatic(EXCEL_TEMPLATE_PATH + EXCEL_TEMPLATE_FILENAME);
                Workbook resultWorkbook = transformer.transformXLS(in, result);

                long accountSeq = param.getSessionLong("loginAccountSeq");
                String tempPath = "canceledMember/" + accountSeq + "_" + EXCEL_TEMPLATE_FILENAME;

                ByteArrayOutputStream baos = new ByteArrayOutputStream();
                resultWorkbook.write(baos);
                byte[] excelBytes = baos.toByteArray();
                s3FileService.upload(TEMP_S3_PREFIX + tempPath, excelBytes, "application/octet-stream");

            } catch (Exception e) {
                logger.error("Excel Write Fail : " + e);
            } finally {
                if (in != null) try {
                    in.close();
                } catch (IOException e) {
                }

