                String existingTestUserYn = param.getString("existingTestUserYn");

                if (!CommonUtil.isNull(existingTestUserYn)) {
	                if ("0".equals(param.get("corporationYn")) && !"Y".equals(param.get("testUserYn"))) {
	                	if (consentFormImg != null && !consentFormImg.isEmpty()) {
