	                		String consentFormFileName = CommonUtil.getRandomStr() + CommonUtil.getFileExt(consentFormImg.getOriginalFilename());
	                		s3FileService.upload(s3Prefix + consentFormFileName, consentFormImg);
	                		param.put("consentFormUrl", "/resources/app/members/" + memberSeq + "/" + consentFormFileName);
	                	} else if (existingConsentFormUrl != null && !existingConsentFormUrl.isEmpty()) {
	                		param.put("consentFormUrl", existingConsentFormUrl);
	                	} else {
	                        throw new LogicException("Personal information consent is required.", "607"); 
	                	}                	
	                } else if (existingConsentFormUrl != null && !existingConsentFormUrl.isEmpty()) {
                		param.put("consentFormUrl", existingConsentFormUrl);
	                }
                }

